begin;
create temp table bio_fixture(label text,id uuid);insert into bio_fixture values('author',gen_random_uuid()),('member',gen_random_uuid()),('other',gen_random_uuid());grant select on bio_fixture to authenticated;
insert into public.allowed_families(name) values('اختبارنبذة');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select id,id::text||'@example.invalid',now(),jsonb_build_object('display_name',label||' علي حسن اختبارنبذة','full_name',label||' علي حسن اختبارنبذة','gender','male','phone',case label when 'author' then '+966500008821' when 'member' then '+966500008822' else '+966500008823' end) from bio_fixture;
update public.profiles set status='active' where id in(select id from bio_fixture);
update public.profiles set role='journalist' where id=(select id from bio_fixture where label='author');
update public.family_settings set journalist_approval=false;
create temp table bio_post(id bigint);grant select,insert on bio_post to authenticated;
select set_config('request.jwt.claim.sub',(select id::text from bio_fixture where label='author'),true);
set local role authenticated;
with p as(insert into public.posts(author_id,title,body,published,mentioned_member_ids) values(auth.uid(),'اختبار رابط خبر','نص اختبار لا يبقى',true,array[(select id from bio_fixture where label='member')]) returning id) insert into bio_post select id from p;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from bio_fixture where label='member'),true);
set local role authenticated;
do $$declare history jsonb;begin
 perform public.account_action('bio','{"bio":"نبذة شخصية تجريبية"}');
 if public.profile_get()->>'bio'<>'نبذة شخصية تجريبية' then raise exception 'Bio did not persist';end if;
 begin perform public.account_action('bio',jsonb_build_object('bio',repeat('ع',301)));raise exception 'LONG_BIO_ACCEPTED';exception when raise_exception then if sqlerrm='LONG_BIO_ACCEPTED' then raise;end if;end;
 insert into public.comments(post_id,author_id,body) select id,auth.uid(),'تعليق مؤقت' from bio_post;
 history=public.account_action('history');
 if not exists(select 1 from jsonb_array_elements(history->'comments') x where x->>'post_id'=(select id::text from bio_post)) or not exists(select 1 from jsonb_array_elements(history->'mentions') x where x->>'post_id'=(select id::text from bio_post)) then raise exception 'Activity links missing';end if;
 update public.profiles set bio='محاولة تعديل آخر' where id=(select id from bio_fixture where label='other');
 if exists(select 1 from public.profiles where id=(select id from bio_fixture where label='other') and bio<>'') then raise exception 'Changed someone else bio';end if;
end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from bio_fixture where label='other'),true);
set local role authenticated;
do $$declare card jsonb;begin card=public.account_action('directory_profile',jsonb_build_object('member',(select id from bio_fixture where label='member')));if card->>'bio'<>'نبذة شخصية تجريبية' or card ? 'phone' or card ? 'email' then raise exception 'Member bio missing or private detail leak';end if;end$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from bio_fixture where label='author'),true);
set local role authenticated;
update public.posts set deleted_at=now() where id=(select id from bio_post);
reset role;
select set_config('request.jwt.claim.sub',(select id::text from bio_fixture where label='member'),true);
set local role authenticated;
do $$declare history jsonb;begin history=public.account_action('history');if exists(select 1 from jsonb_array_elements(history->'comments') x where x->>'post_id'=(select id::text from bio_post)) or exists(select 1 from jsonb_array_elements(history->'mentions') x where x->>'post_id'=(select id::text from bio_post)) or exists(select 1 from public.posts where id=(select id from bio_post)) then raise exception 'Hidden news accessible';end if;end$$;
reset role;
set local role anon;
do $$begin begin perform public.account_action('directory_profile',jsonb_build_object('member',(select id from bio_fixture where label='member')));raise exception 'ANON_ACCEPTED';exception when insufficient_privilege then null;end;end$$;
reset role;
select 'PASS: bio save/read/length/ownership, member privacy, comment and mention news IDs, hidden news and anonymous isolation' as result;
rollback;
